import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"CoreLib 动作","description":"","frontmatter":{},"headers":[],"relativePath":"modules/item/corelib-actions.md","filePath":"modules/item/corelib-actions.md","lastUpdated":0}`),a={name:`modules/item/corelib-actions.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="corelib-动作" tabindex="-1">CoreLib 动作 <a class="header-anchor" href="#corelib-动作" aria-label="Permalink to “CoreLib 动作”">​</a></h1><p>EmakiItem 启用后会向 CoreLib 动作注册表追加主手物品更新、重绘、修复、耐久操作，以及原版 Data Component 新增、修改和删除段。</p><div class="note custom-block"><p class="custom-block-title custom-block-title-default">NOTE</p><p>本页只记录 EmakiItem 注册的段；CoreLib 自带通用段见 <a href="./../corelib/actions.html">CoreLib 动作系统</a>。当前段 ID 只使用下表中的规范名，不再提供历史别名入口。旧的 <code>emakiitem_update</code> 现在写作 <code>item_update</code>，其余同理；旧的冒号写法 <code>emakiitem:component_add</code> 现在写作 <code>item_component_add</code>。</p></div><h2 id="段-id" tabindex="-1">段 ID <a class="header-anchor" href="#段-id" aria-label="Permalink to “段 ID”">​</a></h2><table tabindex="0"><thead><tr><th>段 ID</th><th>用途</th><th>目标要求</th><th>参数</th></tr></thead><tbody><tr><td><code>item_update</code></td><td>强制按 EmakiItem 更新服务刷新主手物品。</td><td><code>REQUIRED_ENTITY</code></td><td>无</td></tr><tr><td><code>item_rerender</code></td><td>通过 CoreLib 物品装配服务重建主手物品展示。</td><td><code>REQUIRED_ENTITY</code></td><td>无</td></tr><tr><td><code>item_repair_amount</code></td><td>修复主手物品指定耐久损伤值。</td><td><code>REQUIRED_ENTITY</code></td><td><code>amount</code></td></tr><tr><td><code>item_damage</code></td><td>增加主手物品指定损伤值。</td><td><code>REQUIRED_ENTITY</code></td><td><code>amount</code></td></tr><tr><td><code>item_set_damage</code></td><td>设置主手物品当前损伤值。</td><td><code>REQUIRED_ENTITY</code></td><td><code>value</code></td></tr><tr><td><code>item_set_durability</code></td><td>设置主手物品剩余耐久值。</td><td><code>REQUIRED_ENTITY</code></td><td><code>value</code></td></tr><tr><td><code>item_component_add</code></td><td>新增一个 Data Component；目标已存在该组件时失败。</td><td><code>OPTIONAL</code></td><td><code>component</code>、<code>value</code>、可选 <code>slot</code></td></tr><tr><td><code>item_component_modify</code></td><td>修改一个已存在的 Data Component；目标缺少该组件时失败。</td><td><code>OPTIONAL</code></td><td><code>component</code>、<code>value</code>、可选 <code>slot</code></td></tr><tr><td><code>item_component_remove</code></td><td>删除一个 Data Component；目标缺少该组件时幂等跳过。</td><td><code>OPTIONAL</code></td><td><code>component</code>、可选 <code>slot</code></td></tr><tr><td><code>item_state_set</code></td><td>设置一个类型化持久 item state。</td><td><code>OPTIONAL</code></td><td><code>key</code>、<code>type</code>、<code>value</code>、可选 <code>slot</code></td></tr><tr><td><code>item_state_add</code></td><td>对数值型持久 item state 增量。</td><td><code>OPTIONAL</code></td><td><code>key</code>、<code>type</code>、<code>amount</code>、可选 <code>slot</code></td></tr><tr><td><code>item_state_remove</code></td><td>删除一个持久 item state。</td><td><code>OPTIONAL</code></td><td><code>key</code>、<code>type</code>、可选 <code>slot</code></td></tr><tr><td><code>item_state_refresh</code></td><td>刷新目标物品并保留其持久 state。</td><td><code>OPTIONAL</code></td><td>可选 <code>slot</code></td></tr></tbody></table><h2 id="门控-id" tabindex="-1">门控 ID <a class="header-anchor" href="#门控-id" aria-label="Permalink to “门控 ID”">​</a></h2><table tabindex="0"><thead><tr><th>门控 ID</th><th>用途</th><th>参数</th><th>提供变量</th></tr></thead><tbody><tr><td><code>item_state_read</code></td><td>读取一个持久 item state 并写入管道变量。</td><td><code>key</code>、<code>type</code>、可选 <code>slot</code></td><td><code>item_state.value</code>、<code>item_state.exists</code>、<code>item_state.key</code>、<code>item_state.type</code></td></tr></tbody></table><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to “参数”">​</a></h2><h3 id="耐久与更新段" tabindex="-1">耐久与更新段 <a class="header-anchor" href="#耐久与更新段" aria-label="Permalink to “耐久与更新段”">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>amount</code></td><td>INTEGER</td><td>是（<code>item_repair_amount</code>、<code>item_damage</code>）</td><td>—</td><td>修复或增加损伤的数量；负数按 0 处理。</td></tr><tr><td><code>value</code></td><td>INTEGER</td><td>是（<code>item_set_damage</code>、<code>item_set_durability</code>）</td><td>—</td><td>目标损伤值或目标剩余耐久值。</td></tr></tbody></table><p><code>item_update</code> 与 <code>item_rerender</code> 不读取参数。</p><h3 id="component-段" tabindex="-1">Component 段 <a class="header-anchor" href="#component-段" aria-label="Permalink to “Component 段”">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>component</code></td><td>STRING</td><td>是</td><td>—</td><td>Data Component ID；省略命名空间时按 <code>minecraft:</code> 解析。</td></tr><tr><td><code>value</code></td><td>STRING</td><td>是（<code>add</code> / <code>modify</code>）</td><td>—</td><td>JSON-ish component 值，支持 JSON 对象/数组、引号字符串、布尔值、数字、<code>null</code> 和普通字符串。结构化值格式错误时该段失败。</td></tr><tr><td><code>slot</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>指定玩家背包槽位；留空时按下面的顺序解析目标。</td></tr></tbody></table><p><code>item_component_remove</code> 只有 <code>component</code> 与 <code>slot</code>，没有 <code>value</code>。</p><h3 id="item-state-段与门控" tabindex="-1">item state 段与门控 <a class="header-anchor" href="#item-state-段与门控" aria-label="Permalink to “item state 段与门控”">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>必填</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>key</code></td><td>STRING</td><td>是（除 <code>item_state_refresh</code>）</td><td>—</td><td>item state 字段名。</td></tr><tr><td><code>type</code></td><td>STRING</td><td>是（除 <code>item_state_refresh</code>）</td><td>—</td><td>item state 类型。</td></tr><tr><td><code>value</code></td><td>STRING</td><td>是（<code>item_state_set</code>）</td><td>—</td><td>要写入的字段值。</td></tr><tr><td><code>amount</code></td><td>DOUBLE</td><td>是（<code>item_state_add</code>）</td><td>—</td><td>数值增量。</td></tr><tr><td><code>slot</code></td><td>STRING</td><td>否</td><td><code>&quot;&quot;</code></td><td>指定玩家背包槽位；槽位名与 Component 段一致。</td></tr></tbody></table><p><code>item_state_refresh</code> 只有可选 <code>slot</code>。<code>item_state_read</code> 是门控而不是段，参数为 <code>key</code>、<code>type</code> 与可选 <code>slot</code>。</p><h2 id="component-目标解析" tabindex="-1">Component 目标解析 <a class="header-anchor" href="#component-目标解析" aria-label="Permalink to “Component 目标解析”">​</a></h2><p>Component 段按以下顺序解析要改的物品：</p><ol><li>参数中显式给出的 <code>slot</code>。</li><li>管道物品（由 <code>create_item</code> 等段发布的 <code>CoreActionKeys.ITEM</code>）。</li><li>目标玩家的主手。</li></ol><p>显式 <code>slot</code> 优先于管道物品：写出槽位是明确指令，不是回退。管道物品会被原地修改，因为后续段读的是同一个引用，替换成新对象会让它们看到未修改的副本。</p><p>三个 Component 段的目标要求是 <code>OPTIONAL</code> 而不是 <code>REQUIRED_ENTITY</code>：只要管道里有物品，没有玩家目标也能改。</p><h3 id="支持的槽位" tabindex="-1">支持的槽位 <a class="header-anchor" href="#支持的槽位" aria-label="Permalink to “支持的槽位”">​</a></h3><p>槽位名沿用 CoreLib 的统一槽位表：</p><ul><li>主手：<code>mainhand</code>、<code>main_hand</code>、<code>hand</code></li><li>副手：<code>offhand</code>、<code>off_hand</code></li><li>护甲：<code>helmet</code>、<code>chestplate</code> / <code>chest</code>、<code>leggings</code> / <code>legs</code>、<code>boots</code></li><li>背包索引：<code>0</code> 到 <code>35</code>，也可写成 <code>slot_12</code>、<code>hotbar_0</code></li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to “示例”">​</a></h2><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_update&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_repair_amount amount=25&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_damage amount=10&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_set_durability value=100&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_component_add component=max_stack_size value=16&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_component_modify component=enchantment_glint_override value=true slot=mainhand&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | item_component_remove component=custom_name slot=offhand&#39;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # 改管道物品而不是背包里的物品</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;self | create_item item_source=minecraft-diamond_sword | item_component_add component=max_stack_size value=1 | send_item&#39;</span></span></code></pre></div><p>带空格或结构化内容的 <code>value</code> 要加引号：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>self | item_component_modify component=custom_name value=&#39;&lt;gold&gt;锻造之刃&lt;/gold&gt;&#39;</span></span>
<span class="line"><span>self | item_component_add component=custom_data value=&#39;{&quot;emaki&quot;:{&quot;source&quot;:&quot;forge&quot;}}&#39;</span></span></code></pre></div><h2 id="使用提示" tabindex="-1">使用提示 <a class="header-anchor" href="#使用提示" aria-label="Permalink to “使用提示”">​</a></h2><ul><li>更新与耐久段作用于目标玩家主手物品，主手为空时跳过；成功时输出 <code>changed</code>、<code>damage</code>、<code>max_damage</code>。</li><li><code>item_set_durability</code> 在物品没有最大耐久时不做修改；损伤值会被钳制到 <code>[0, max_damage]</code>，降到上限以下时自动清除修复禁用标记。</li><li><code>item_component_add</code> 遇到已存在的组件、<code>item_component_modify</code> 遇到缺失的组件都会以 <code>REJECTED</code> 失败而不是静默纠正，这两种情况都是配置写错了。<code>item_component_remove</code> 遇到缺失组件则按跳过处理。</li><li>组件修改通过 CoreLib <code>ConfiguredItemDefinition</code> patch 应用，会保留第三方物品来源身份、PDC 和未涉及的组件。</li><li>Component 段成功时输出 <code>component</code>、<code>target</code>、<code>changed</code>、<code>existed_before</code>；<code>target</code> 是槽位名或 <code>pipeline:item</code>。</li><li>目标物品为空气时跳过；三种解析路径都没找到物品时该段失败。</li></ul>`,31)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};